    /* §3.2 grade range text: "B+ (87% up to 90%)" · top "A+ (97% and above)" · F "F (below 60%)" */
    const range = li === 0 ? `${letter} (${L[li][1]}% and above)` : letter === 'F' ? `F (below ${up[1]}%)` : `${letter} (${L[li][1]}% up to ${up[1]}%)`;
    /* §3.2 only when whole class graded: prev start − displayed value ("1.45 points below a C"); none at top letter */
