  const HOLE_RE = /\{\{\s*([^}]+?)\s*\}\}/g;
  const WHOLE_RE = /^\s*\{\{\s*([^}]+?)\s*\}\}\s*$/;

  /* ---- 1.1 Value lookup ---------------------------------------------------- */

